    echo -e ""
    echo -e "Returns the created purchase order id. Suggested line items are generated
with the current reorder quantity per product." | paste -sd' ' - | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
